pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // General rule: for any deployer address d, the deployed contract's owner() equals the deployer.
    // We fuzz the deployer address as an input by impersonating it when deploying a new instance.
    // The reference implementation satisfies this for all deployers; the mutant that returns address(0)
    // will violate it for many deployers (the fuzzer will find one).
    function testFuzz_property(address deployer) public {
        // keep wide domain but avoid zero address which is a valid edge-case; we still allow it so fuzzer can explore
        // Deploy a fresh instance from the fuzzed deployer (prank the deployer account)
        vm.prank(deployer);
        C local = new C(address(this));

        // Query owner via public getter. This should succeed (not revert) and return the deployer for the reference.
        address observed;
        bool ok;
        try local.owner() returns (address o) {
            observed = o;
            ok = true;
        } catch {
            // If the call reverts (shouldn't for either ref or mutant), mark as not ok
            observed = address(0);
            ok = false;
        }

        // Single assertion: owner() call must succeed and equal the deployer address.
        // Reference: true for all deployers. Mutant: returns address(0) (or differs), so for many deployers this fails.
        assertTrue(ok && observed == deployer);
    }
}

