pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // General rule to check: owner() always returns the stored owner (the deployer),
    // i.e., owner() != msg.sender for some callers; the mutant returns msg.sender instead.
    // We fuzz the caller address to let the fuzzer find a caller for which owner() != caller
    // (which should always hold for at least some addresses) — the reference returns the
    // deployer while the mutant would return the caller, causing a differing return.
    function testFuzz_property(address caller) public {
        // Avoid the trivial case where the fuzzed caller equals the deployer (the test contract)
        // so that we can observe a difference: keep domain wide but exclude the deployer address
        // because for that address both contracts would return the same value.
        vm.assume(caller != address(this));

        // Call owner() as the fuzzed caller, capturing whether the call succeeded and its return
        // We must observe c only via its public surface. Use try/catch to call owner() as caller.
        bool ok;
        address retval;
        // perform call as the fuzzed caller
        vm.prank(caller);
        try c.owner() returns (address v) {
            ok = true;
            retval = v;
        } catch {
            ok = false;
            retval = address(0);
        }

        // Exactly one assertion: in the correct contract, for any caller != deployer, owner() must
        // return the deployer (address(this)), i.e., retval == address(this) and the call must succeed.
        // The mutant that returns msg.sender will make retval == caller for such callers, so this
        // assertion will fail on the mutant for some fuzzed caller values.
        assertTrue(ok && retval == address(this));
    }
}

