pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed caller: contract or EOA address that will call owner()
    function testFuzz_property(address caller) public {
        // keep domain wide but avoid the zero address which some callers may not use
        vm.assume(caller != address(0));

        // call owner() as the fuzzed caller
        bool ok;
        try C(address(c)).owner{gas: gasleft()}() returns (address v) {
            // owner() returned a value without reverting
            // check whether returned value equals the deployed owner (address(this))
            // but we must perform the call as the fuzzed caller to let msg.sender differ
            ok = (v == thisAddress());
        } catch {
            ok = false;
        }

        // We need to actually perform the call with msg.sender == caller. Use vm.prank.
        // However try-catch above was with current msg.sender; redo properly invoking via prank and capture result.
        vm.prank(caller);
        bool ok2;
        try C(address(c)).owner() returns (address v2) {
            ok2 = (v2 == thisAddress());
        } catch {
            ok2 = false;
        }

        // Single assertion: reference contract always reports deployer (thisAddress()) as owner for any caller
        assertTrue(ok2);
    }

    // helper to get the deployer address that constructed c in setUp (this contract)
    function thisAddress() internal view returns (address) { return address(this); }
}

