pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

// This test verifies: owner() equals the deployer (constructor msg.sender) for all deployments.
// The mutant changes owner() to return tx.origin, which differs when a contract deploys C.

contract DeployerContract {
    function deploy(address liquidityReceive) external returns (address) {
        C instance = new C(liquidityReceive);
        return address(instance);
    }
}

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    // fuzzed parameter: an arbitrary address that will act as liquidityReceiveAddress for a contract deployment
    function testFuzz_property(address liquidityReceive) public {
        // keep the fuzzed address wide but avoid zero which is a valid but uninteresting value
        // zero is allowed too, but we don't need to exclude it. No tight bounds.

        // 1) For the reference contract deployed in setUp(), owner() must equal the deployer (this test contract)
        address owner1 = c.owner();
        // owner1 should be the deployer, which in setUp() was address(this)
        assertTrue(owner1 == address(this));

        // 2) Now deploy C via another contract. In the correct implementation, owner() should be the deployer contract's address
        DeployerContract d = new DeployerContract();
        address deployedAddr = d.deploy(liquidityReceive);
        C c2 = C(deployedAddr);

        // Call owner() on the instance deployed by contract d. The correct contract returns the deployer (which is address(d)).
        // The mutant returning tx.origin would instead return the original EOA that initiated the transaction (address(this)),
        // so for some inputs (i.e. when deployment is done by a contract) values differ and the mutant breaks.
        address owner2 = c2.owner();

        // Single assertion for the universal property: owner equals the deployer contract for this deployment path.
        assertTrue(owner2 == address(d));
    }
}

// No additional helpers required beyond DeployerContract above.

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract ForwardCaller {
    C public target;
    constructor(C _target) {
        target = _target;
    }

    function callOwner() external view returns (address) {
        return target.owner();
    }
}

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed parameter: an address that will be used as the external EOA caller of ForwardCaller
    function testFuzz_property(address caller) public {
        // Keep domain wide but non-zero to avoid the zero-address EOA which is awkward to prank
        vm.assume(caller != address(0));

        // Deploy a forwarding contract (adversarial counterpart) that calls c.owner() from its own context
        ForwardCaller f = new ForwardCaller(c);

        // Make the fuzzed EOA be the tx.origin when calling through the forwarder
        vm.prank(caller);
        address ownerReturnedByCall = f.callOwner();

        // Directly call owner() from the EOA caller (msg.sender == tx.origin == caller)
        vm.prank(caller);
        address ownerDirect = c.owner();

        // General property: In the correct contract, owner() should be the immediate msg.sender,
        // so calling through the forwarder (where msg.sender==address(f)) returns the forwarder's address,
        // and calling directly returns the EOA's address; these two are equal only if caller == address(f).
        // The mutant returning tx.origin would make the forwarder-call return tx.origin (caller),
        // thus ownerReturnedByCall == ownerDirect for the mutant, but for the correct contract they differ
        // whenever caller != address(f). We assert the universal property that for any caller,
        // ownerReturnedByCall == ownerDirect implies caller == address(f). Equivalently, if caller != address(f)
        // then ownerReturnedByCall != ownerDirect. This holds for the reference but is violated by the mutant
        // (which would make them equal when caller != address(f)).

        bool provable = true;
        if (caller != address(f)) {
            provable = (ownerReturnedByCall != ownerDirect);
        } else {
            provable = (ownerReturnedByCall == ownerDirect);
        }

        assertTrue(provable);
    }
}

