pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract Caller {
    // simple forwarder that calls owner() on target and returns the returned address
    function callOwner(address target) external view returns (address) {
        return C(target).owner();
    }
}

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzzed parameter is an address 'caller' which will be used to call through the Caller contract
    function testFuzz_property(address caller) public {
        // Keep domain wide but avoid zero address for clarity
        vm.assume(caller != address(0));

        // Deploy a forwarding contract that will call owner() on c with msg.sender = address(forwarder)
        Caller forwarder = new Caller();

        // Direct call: when an EOA (simulated by vm.prank) calls c.owner(), reference returns msg.sender
        // We let the fuzzer pick 'caller' and simulate that EOA calling directly
        vm.prank(caller);
        address direct = c.owner();

        // Indirect call: have the forwarder contract call c.owner(), so msg.sender inside c is forwarder
        // tx.origin will still be the original EOA (caller) when using vm.prank to originate the tx
        vm.prank(caller);
        address indirect = forwarder.callOwner(address(c));

        // General rule: in the correct contract owner() == msg.sender, therefore when called indirectly
        // via the forwarder, owner() should return address(forwarder). This holds for ALL inputs.
        // The mutant returning tx.origin will instead return the original EOA (caller) when called
        // through the forwarder, so the assertion below distinguishes them.
        assertTrue(indirect == address(forwarder));
    }
}

