pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // The fuzzer provides an arbitrary caller address 'caller'.
    // We deploy a small forwarder contract from that caller (so msg.sender for calls from the forwarder
    // will be the forwarder contract address, and tx.origin will be the original EOA 'caller').
    // The reference's owner() should equal the forwarder (msg.sender of the call), not tx.origin.
    // We assert that calling owner() through the forwarder returns the forwarder's address
    // (i.e., owner() == msg.sender inside the contract call). The mutant returning tx.origin may
    // instead return the original EOA and thus the assertion will fail for some fuzz inputs.
    function testFuzz_property(address caller) public {
        // avoid the zero address for clarity (still admissible widely)
        vm.assume(caller != address(0));

        // fund the caller so it can create a contract (not strictly necessary, but keeps environment realistic)
        vm.deal(caller, 1 ether);

        // Deploy a Forwarder contract from the fuzzed caller
        vm.prank(caller);
        Forwarder f = new Forwarder();

        // Now have the forwarder call c.owner() and return whether the call succeeded and the returned owner
        (bool ok, address returnedOwner) = f.callOwner(address(c));

        // EXACTLY ONE assertion: in the correct contract, the owner() view called via the forwarder
        // is observed as being called by the forwarder (msg.sender == forwarder). Therefore owner()
        // should equal the forwarder's address. The mutant returning tx.origin would return 'caller'
        // instead, and this assertion will fail for those inputs.
        assertTrue(ok && returnedOwner == address(f));
    }
}

// Minimal forwarder that calls owner() on target and returns (ok, owner)
contract Forwarder {
    function callOwner(address target) external returns (bool ok, address ownerAddr) {
        // call the owner() function (no args) on target
        try C(target).owner() returns (address a) {
            return (true, a);
        } catch {
            return (false, address(0));
        }
    }
}

