pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // General rule to check: when called directly by any EOA caller, the reference's owner() returns the stored owner (the deployer/owner)
    // We fuzz an arbitrary caller address 'caller'. We will have that caller call c.owner() directly (via vm.prank) and
    // capture the returned address. The reference contract should always return the same owner regardless of caller (owner is stored and returned by owner()).
    // The mutant that returns tx.origin can differ when the call originates through a contract forwarder; to let the fuzzer explore, we also deploy
    // a Forwarder and let the fuzzer choose whether to call directly or via the forwarder by picking a boolean flag 'viaForwarder'.
    // However per the problem constraints we must have the test's single assertion be a universal property the reference satisfies and the mutant breaks for some inputs.

    function testFuzz_property(address caller, bool viaForwarder) public {
        // Keep caller non-zero to be a meaningful EOA in fuzzing context
        if (caller == address(0)) caller = address(1);

        // Deploy a simple forwarder contract that will call c.owner() and return its result
        Forwarder f = new Forwarder();

        // If viaForwarder is true, we want the call to be issued by the forwarder contract but with tx.origin == caller.
        // Achieve that by: vm.prank(caller); f.callOwner(address(c)); which makes tx.origin == caller and msg.sender inside c.owner() == address(f)
        address returned;
        if (viaForwarder) {
            vm.prank(caller);
            returned = f.callOwner(address(c));
        } else {
            // Direct call: set msg.sender == caller, so owner()'s msg.sender == caller context for the reference
            vm.prank(caller);
            returned = c.owner();
        }

        // Single assertion: In the reference implementation, owner() always returns the stored owner address (the deployer set at construction: address(this) in setUp())
        // So regardless of caller or forwarding, owner() as returned to the caller equals the stored owner value, which is accessible by calling c.owner() directly from the test process (vm.prank allowed above).
        // We assert that the value we observed equals the owner returned when reading directly from the test runner (i.e., calling owner() with no prank; msg.sender == address(this)).

        address direct = c.owner();
        assertTrue(returned == direct);
    }
}

contract Forwarder {
    function callOwner(address caddr) external returns (address) {
        // forward a call to owner() and return the addressed result
        (bool ok, bytes memory data) = caddr.call(abi.encodeWithSignature("owner()"));
        require(ok, "call failed");
        return abi.decode(data, (address));
    }
}

