pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzz the deployer-like actor address to ensure owner() equals the deployer for any caller
    function testFuzz_property(address fuzzDeployer) public {
        // Keep domain wide but non-zero to avoid accidental zero-address edge if desired
        // We still allow zero; no tight constraints so mutant can be found

        // We will simulate calls to owner() as if from fuzzDeployer by using vm.prank.
        // The general property: owner() should equal the original deployer (address(this) of setUp deployer)
